"""Freeze varied conversational corrections with complete historical rehearsal."""
import copy,hashlib,json
from pathlib import Path
R=Path(__file__).resolve().parent
P=R.parent/'requirements-draft-v19'
read=lambda p:[json.loads(x) for x in p.read_text().splitlines()]
old=read(P/'acquisition.jsonl')
systems={t:next(x['messages'][0]['content'] for x in old if x['task']==t) for t in ['draft','bounds']}
variants=[]
def add(name,turns,description,title,questions=None,literals=None):
    assert len(turns)%2==1,name
    messages=[{'role':'system','content':systems['draft']}]+[{'role':'user' if i%2==0 else 'assistant','content':s} for i,s in enumerate(turns)]
    messages.append({'role':'assistant','content':json.dumps({'description':description,'questions':questions or [],'summary':title},ensure_ascii=False,separators=(',',':'))})
    row={'id':name,'task':'draft','messages':messages}
    if literals:row['required_literals']=literals
    variants.append(row)

