assert len(variants)==32
# Fresh dialogues are authored separately rather than obtained by renaming training rows.
fresh=read(R/'fresh-drafts.jsonl')
acquisition=copy.deepcopy(old)
for file in ['check.jsonl','release-dialogues.jsonl']:
 for row in read(P/file):
    row['id']='v20-'+row['id'];acquisition.append(row)
assert len(acquisition)==669
# Preserve the exact previous numeric/sort rehearsal slice irrespective of ID conventions.
rehearsal=read(P/'replay-train.jsonl')[-112:]
assert len(rehearsal)==112 and all(x['task'] in ['bounds','general'] for x in rehearsal)
train=acquisition+variants*4+read(P/'semantic-variants.jsonl')+rehearsal
train+=read(P/'release-dialogues.jsonl')*3
for name,rows in [('variants.jsonl',variants),('acquisition.jsonl',acquisition),('train.jsonl',train)]:
 (R/name).write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows))
protocol={'parent':'../requirements-draft-v19/replay-adapter','parent_sha256':hashlib.sha256((P/'replay-adapter/adapters.safetensors').read_bytes()).hexdigest(),'steps':len(train),'layers':32,'epochs':1,'seed':42,'learning_rate':1e-6,
 'recipe':'669 historical targets once, 32 authored conversational variants four times, 32 previous balanced variants, 112 numeric/sort rehearsal cases and 16 newly inspected diverse targets three extra times.',
 'gate':'Retain all 669 familiar cases before candidate fresh inference. Preserve every parent success on freshly authored conversations and numeric checks. Runtime/live dialogue release gates remain separate.',
 'limits':'Synthetic non-blind study. New language coverage and replay weights change together; no isolated causal claim.',
 'hashes':{name:hashlib.sha256((R/name).read_bytes()).hexdigest() for name in ['train.jsonl','acquisition.jsonl','variants.jsonl','fresh-drafts.jsonl','check.jsonl']}}
(R/'protocol.json').write_text(json.dumps(protocol,indent=2)+'\n')
print('Frozen',len(train),'presentations;',len(variants),'new conversational variants;',len(acquisition),'retention cases;',len(fresh),'fresh drafts.')
